create extension if not exists pgcrypto;create table public.users(id uuid primary key references auth.users(id) on delete cascade,username text unique not null,avatar text,created_at timestamptz default now());create table public.books(id uuid primary key default gen_random_uuid(),title text not null,author text not null,description text,cover_url text not null,user_id uuid references public.users(id) on delete cascade,created_at timestamptz default now());create table public.ratings(id uuid primary key default gen_random_uuid(),book_id uuid references public.books(id) on delete cascade,user_id uuid references public.users(id) on delete cascade,rating smallint check(rating between 1 and 10),created_at timestamptz default now(),unique(book_id,user_id));create table public.comments(id uuid primary key default gen_random_uuid(),book_id uuid references public.books(id) on delete cascade,user_id uuid references public.users(id) on delete cascade,text text not null,created_at timestamptz default now());alter table public.users enable row level security;alter table public.books enable row level security;alter table public.ratings enable row level security;alter table public.comments enable row level security;create policy "profiles readable" on public.users for select using(true);create policy "books readable" on public.books for select using(true);create policy "owners create books" on public.books for insert with check(auth.uid()=user_id);create policy "ratings readable" on public.ratings for select using(true);create policy "own rating" on public.ratings for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "comments readable" on public.comments for select using(true);create policy "own comments" on public.comments for all using(auth.uid()=user_id) with check(auth.uid()=user_id);